  float calibrationHumidity = 60.5; // Replace with actual humidity value

  // Calculate the error in temperature and humidity values
  float temperatureError = temperature - calibrationTemperature;
  float humidityError = humidity - calibrationHumidity;

  // Calculate the calibration coefficients (beta and alpha)
  float beta = (temperatureError / 100.0); // Calibration coefficient for temperature
  float alpha = (humidityError / 100.0); // Calibration coefficient for humidity

  // Print the calibration coefficients
  Serial.println("Calibration Coefficients:");
  Serial.print("Beta (Temperature): ");
  Serial.print(beta);
  Serial.println();
  Serial.print("Alpha (Humidity): ");
  Serial.print(alpha);
  Serial.println();

  delay(10000); // Wait for 10 seconds before taking the next reading
}
